"""Standalone presentation of actual recorded runs; animation replays stored events."""
import json


def render(directory, rows, metadata):
    events = [json.loads(line) for line in (directory / "events.jsonl").read_text().splitlines()]
    data = json.dumps(dict(rows=rows, events=events, records=metadata["runs"], created=metadata["created_epoch_ns"])).replace("<", "\\u003c")
    page = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CAN-FD • Fault recovery laboratory</title>
<style>
:root{--ink:#203b54;--paper:#edf3f8;--line:#cad7e3;--blue:#215bb5;--green:#087769;--red:#b33940;--amber:#986500}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}
main{max-width:1180px;margin:auto;padding:38px 28px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:2px solid var(--ink);padding-bottom:20px}
h1{font:600 clamp(28px,4vw,44px)/1.1 'Trebuchet MS',sans-serif;margin:8px 0}h2{font-size:19px;margin:0 0 14px}small,.label{font:12px/1.4 monospace;text-transform:uppercase;letter-spacing:.06em}
.scope{background:#dce8f4;border-left:4px solid var(--blue);padding:14px 20px;margin:24px 0}.layout{display:grid;grid-template-columns:300px 1fr;gap:24px}section,aside{background:white;padding:24px;border:1px solid var(--line);border-radius:10px}
select,button,input{font:inherit}select{width:100%;padding:10px;border:1px solid var(--line);background:white;color:var(--ink)}button{padding:8px 17px;border:1px solid var(--blue);border-radius:5px;background:var(--blue);color:white;cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--amber);outline-offset:3px}
.metric{padding:13px 0;border-bottom:1px solid var(--line)}.metric b{display:block;font:600 23px monospace}.metric span{font-size:13px}.grid{display:grid;grid-template-columns:repeat(10,1fr);gap:6px;margin:20px 0}.frame{background:#edf1f5;border:1px solid var(--line);border-radius:4px;text-align:center;padding:11px 0;font:13px monospace}.rx{background:#d9eee8;border-color:var(--green);color:var(--green)}.drop{background:#f9e2e3;border-color:var(--red);color:var(--red)}.tx{background:#dce8fc;border-color:var(--blue)}
.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}input{flex:1;min-width:160px}#event{min-height:56px;font:14px monospace;background:var(--paper);padding:12px;margin:16px 0;overflow-wrap:anywhere}.legend{font-size:13px;color:#546b7f}.status{font:14px monospace;overflow-wrap:anywhere}.table{overflow:auto;margin-top:24px;background:white;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#dce8f4}.ok{color:var(--green)}.fail{color:var(--red)}footer{margin-top:24px;font-size:13px}a{color:var(--blue)}@media(max-width:760px){.layout{grid-template-columns:1fr}main{padding:20px 14px}.grid{grid-template-columns:repeat(7,1fr)}header{display:block}}
</style><main>
<header><div><small>Phase 2 / measured software execution</small><h1>41 frames. Every loss accounted for.</h1></div><div class="label">ML-DSA-44<br>Ascon-AEAD128<br>Selective NACK</div></header>
<div class="scope"><b>Real cryptography. Real local socket traffic. Deliberate fault injection.</b><br>This is a replay of recorded executions, not a live CAN bus. Physical bitrate, bus arbitration and wire overhead were not measured. Animation speed is for presentation; timestamps are the recorded host measurements.</div>
<div class="layout"><aside><h2>Choose an execution</h2><label for="run">Scenario and trial</label><select id="run"></select><p id="status" class="status"></p><div id="metrics"></div><p class="legend">A successful transfer requires complete assembly, a valid Ascon tag and a valid ML-DSA signature. Safe fallback here means the software denies activation.</p></aside>
<section><h2>Receiver’s fragment buffer</h2><div class="legend">Gray: awaiting · Blue: sent · Red: discarded · Green: received<br>Frame indices 0–40. Final fragment: 36 active bytes + 24 padding bytes.</div><div id="frames" class="grid"></div><div class="controls"><button id="play">Replay</button><button id="reset">Reset</button><label for="position">Event</label><input id="position" type="range" min="0" value="0"></div><div id="event" aria-live="polite"></div><h2>Recovery rounds</h2><div id="rounds"></div></section></div>
<div class="table"><table><thead><tr><th>Execution</th><th>Fault</th><th>Result</th><th>Retries</th><th>Host latency (µs)</th><th>Recovered frames</th></tr></thead><tbody id="runs"></tbody></table></div>
<footer><b>Measurement boundary:</b> first local data send through authentication or failure; enrollment is excluded; signing and encryption are measured separately in the manifest. No ISO 26262 certification or hardware PUF claim. The experimental time budget is configurable.<br><a href="fault_recovery_runs.csv">40-column CSV</a> · <a href="events.jsonl">Raw frame events</a> · <a href="manifest.json">Provenance and strict-contract gaps</a> · <a href="measurement_profile.json">Software measurement profile</a></footer>
</main><script>const D=__DATA__;
const $=id=>document.getElementById(id);let selected=[],timer=null;
const cells=Array.from({length:41},(_,i)=>{let e=document.createElement('div');e.className='frame';e.textContent=i;$('frames').append(e);return e});
D.rows.forEach((r,i)=>{let o=document.createElement('option');o.value=i;o.textContent=`${i+1}. ${D.records[i].injection} [${r.injected_dropped_frame_indices}] / trial ${r.trial_idx}`;$('run').append(o);let tr=document.createElement('tr');[i+1,D.records[i].injection,r.termination_status_code,r.recovery_rounds,r.end_to_end_latency_us.toFixed(3),r.round_1_recovered_frames+r.round_2_recovered_frames+r.round_3_recovered_frames].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});$('runs').append(tr)});
function stop(){clearInterval(timer);timer=null;$('play').textContent='Replay'}
function draw(){const n=Number($('position').value);cells.forEach(e=>e.className='frame');for(const e of selected.slice(0,n)){if(e.can_id==='0x200'&&['tx','rx','drop'].includes(e.event))cells[e.frame_idx].className='frame '+e.event}let e=selected[n-1];$('event').textContent=e?`${n}/${selected.length} · ${(e.t_ns/1000).toFixed(3)} µs · ${e.event} · round ${e.round} ${e.can_id||''} ${e.frame_idx!=null?'frame '+e.frame_idx:''} ${e.status||''}`:'Ready to replay recorded events.'}
function choose(){stop();const i=Number($('run').value),r=D.rows[i];selected=D.events.filter(e=>e.run_id===r.run_id);$('position').max=selected.length;$('position').value=0;$('status').textContent=r.termination_status_code;$('status').className='status '+(r.recovery_success?'ok':'fail');$('metrics').replaceChildren();[['Host latency',r.end_to_end_latency_us.toFixed(3)+' µs'],['Retransmitted data frames',r.retransmitted_frames_count],['NACK frames',r.nack_frames_issued_count],['Experimental budget exceeded',r.ftti_violation_flag?'Yes':'No']].forEach(([label,value])=>{let d=document.createElement('div');d.className='metric';let b=document.createElement('b');b.textContent=value;let s=document.createElement('span');s.textContent=label;d.append(b,s);$('metrics').append(d)});$('rounds').replaceChildren();let maps=r.nack_bitmaps_issued_hex.split(';');for(let j=1;j<=r.recovery_rounds;j++){let p=document.createElement('p');p.className='status';p.textContent=`Round ${j}: ${r['round_'+j+'_requested_frames']} requested → ${r['round_'+j+'_recovered_frames']} recovered · ${maps[j-1]}`;$('rounds').append(p)}if(!r.recovery_rounds)$('rounds').textContent='No retransmission requested.';draw()}
$('run').onchange=choose;$('position').oninput=()=>{stop();draw()};$('reset').onclick=()=>{stop();$('position').value=0;draw()};$('play').onclick=()=>{if(timer){stop();return}if(Number($('position').value)===selected.length)$('position').value=0;$('play').textContent='Pause';timer=setInterval(()=>{$('position').value=Number($('position').value)+1;draw();if(Number($('position').value)>=selected.length)stop()},70)};choose();
</script></html>'''
    (directory / "report.html").write_text(page.replace("__DATA__", data))
